async def receive_audio(session, p_out):
    """Loops over session responses, plays audio aloud, and prints text transcripts."""
    try:
        async for response in session.receive():
            if response.server_content and response.server_content.model_turn:
                for part in response.server_content.model_turn.parts:
                    # If the payload includes text, print it for debugging
                    if part.text:
                        print(part.text, end="", flush=True)
                    # If the payload includes raw audio, write it to the output speakers
                    if part.inline_data:
                        # Writing to PyAudio in background thread to avoid blocking the event loop
                        await asyncio.to_thread(p_out.write, part.inline_data.data)
    except asyncio.CancelledError:
        pass
    except Exception as e:
        print(f"\n[Receive Error] {e}")
